import itertools
from pysat.solvers import Glucose3

n = 17
edges = []
edge_vars = {}
var_counter = 1

for u in range(n):
    for v in range(u + 1, n):
        edges.append((u, v))
        edge_vars[(u, v)] = var_counter
        edge_vars[(v, u)] = var_counter
        var_counter += 1

solver = Glucose3()

# At least 30 edges
# We can use a cardinality constraint, or just simple sequential counter
# Actually, PySAT has CardEnc
from pysat.card import CardEnc, EncType
clauses = CardEnc.atleast(lits=[edge_vars[e] for e in edges], bound=30, encoding=EncType.seqcounter, top_id=var_counter)
for clause in clauses.clauses:
    solver.add_clause(clause)
var_counter = clauses.nv + 1

# Girth >= 7 (no cycles of length 3, 4, 5, 6)
def add_no_cycle(length):
    for p in itertools.permutations(range(n), length):
        # To avoid duplicates, only consider permutations where p[0] is the minimum element
        # and p[1] < p[-1]
        if p[0] == min(p) and p[1] < p[-1]:
            cycle_edges = [(p[i], p[(i+1)%length]) for i in range(length)]
            solver.add_clause([-edge_vars[e] for e in cycle_edges])

add_no_cycle(3)
add_no_cycle(4)
add_no_cycle(5)
add_no_cycle(6)

# 4-colorable
# Variables for colors: C_{v, c}
color_vars = {}
for v in range(n):
    for c in range(4):
        color_vars[(v, c)] = var_counter
        var_counter += 1

for v in range(n):
    # At least one color
    solver.add_clause([color_vars[(v, c)] for c in range(4)])
    # At most one color
    for c1 in range(4):
        for c2 in range(c1 + 1, 4):
            solver.add_clause([-color_vars[(v, c1)], -color_vars[(v, c2)]])

for u in range(n):
    for v in range(u + 1, n):
        for c in range(4):
            solver.add_clause([-edge_vars[(u, v)], -color_vars[(u, c)], -color_vars[(v, c)]])

print("Solving...")
if solver.solve():
    print("SAT")
    model = solver.get_model()
    result_edges = [e for e in edges if model[edge_vars[e] - 1] > 0]
    print(result_edges)
else:
    print("UNSAT")

from pysat.solvers import Glucose4
from pysat.card import CardEnc, EncType
import itertools

n = 17
edges = []
edge_vars = {}
var_counter = 1

for u in range(n):
    for v in range(u + 1, n):
        edges.append((u, v))
        edge_vars[(u, v)] = var_counter
        edge_vars[(v, u)] = var_counter
        var_counter += 1

solver = Glucose4()

def add_no_cycle(length):
    for p in itertools.permutations(range(n), length):
        if p[0] == min(p) and p[1] < p[-1]:
            cycle_edges = [(p[i], p[(i+1)%length]) for i in range(length)]
            solver.add_clause([-edge_vars[e] for e in cycle_edges])

add_no_cycle(3)
add_no_cycle(4)

# Let's just check if 18 edges is possible
clauses = CardEnc.atleast(lits=[edge_vars[e] for e in edges], bound=18, encoding=EncType.seqcounter, top_id=var_counter)
for clause in clauses.clauses:
    solver.add_clause(clause)

print("Solving for 18 edges, girth >= 5...")
if solver.solve():
    print("SAT")
else:
    print("UNSAT")
